module jt054156_p24(
    input  wire a1,
    input  wire b1,
    input  wire a2,
    input  wire b2,
    input  wire a3,
    input  wire b3,
    input  wire a4,
    input  wire b4,
    input  wire sa,
    input  wire sb,
    output wire x1,
    output wire x2,
    output wire x3,
    output wire x4
);

wire select_a = ~sa &  sb;
wire select_b =  sa & ~sb;

assign x1 = (select_a & a1) | (select_b & b1);
assign x2 = (select_a & a2) | (select_b & b2);
assign x3 = (select_a & a3) | (select_b & b3);
assign x4 = (select_a & a4) | (select_b & b4);

endmodule

module jt054156_t2b(
    input  wire a,
    input  wire b,
    input  wire s1,
    input  wire s2,
    output wire x
);

wire select_a = ~s1 & s2;
wire select_b = s1 & ~s2;
wire selected = (select_a & a) | (select_b & b);

assign x = ~selected;

endmodule

module jt054156_t5a(
    input  wire a1,
    input  wire a2,
    input  wire s1,
    input  wire s2,
    input  wire s5,
    input  wire s6,
    input  wire s3,
    input  wire s4,
    input  wire b1,
    input  wire b2,
    output wire x
);

wire select_a1 = ~s1 &  s2;
wire select_a2 =  s1 & ~s2;
wire select_b1 = ~s3 &  s4;
wire select_b2 =  s3 & ~s4;
wire select_a  = ~s5 &  s6;
wire select_b  =  s5 & ~s6;
wire mux_a     = (select_a1 & a1) | (select_a2 & a2);
wire mux_b     = (select_b1 & b1) | (select_b2 & b2);
wire selected  = (select_a & mux_a) | (select_b & mux_b);

assign x = ~selected;

endmodule

module jt054156_c43(
    input  wire       ck,
    input  wire [3:0] d,
    input  wire       load_n,
    input  wire       en,
    input  wire       ci,
    input  wire       clear_n,
    output reg  [3:0] q,
    output wire       co
);

always @(posedge ck or negedge clear_n) begin
    if (!clear_n) begin
        q <= 4'd0;
    end else if (!load_n) begin
        q <= d;
    end else if (en & ci) begin
        q <= q + 1'b1;
    end
end

assign co = &{ q, ci };

endmodule

