// Page-12 scroll capture and test-select cluster.
//
// This covers the visually bounded block from E52A/H162 through the
// C25/C15/H3 scroll pipeline and the J8B/J10B/J9A SCROLLY[2:0] test muxes.
// The H36 rail is generated by the adjacent VD/COL flip-enable selector
// cluster; the connected page-12 output wrapper supplies it.
module jt054156_page12_scroll_capture(
    input  wire        n186_x0,
    input  wire        n186_x3,
    input  wire        pin_test,
    input  wire        h36_y,
    input  wire [8:3]  scrollx,
    input  wire [2:0]  scrolly,
    output wire        e52a_y,
    output wire        h162_y,
    output wire        e14a_y,
    output reg        h156_q,
    output reg        n186_x3_dly,
    output wire        n186_x3_dly_n,
    output wire [8:3]  scrollx_l,
    output wire [2:0]  scrolly_l,
    output wire [8:3]  scrollx_xor,
    output wire [2:0]  scrolly_xor,
    output wire        j18a_y,
    output wire        j6a_y,
    output wire [2:0]  scrolly_t2b_x,
    output wire [2:0]  scrolly_mux
);

reg [3:0] c25_q, c15_q, h3_q;
reg     c7_q, e22_q, f8_q;
reg     h14_q, h17_q, h20_q;
wire [3:0] c25_d, c15_d, h3_d;
assign c25_d = { scrollx[6], scrollx[5], scrollx[4], scrollx[3] };
assign c15_d = { e22_q,     c25_q[3],   c25_q[2],   c25_q[1]   };
assign h3_d  = { h20_q,     h17_q,      h14_q,      f8_q       };

assign scrollx_l[3] = c7_q;
assign scrollx_l[4] = c15_q[0];
assign scrollx_l[5] = c15_q[1];
assign scrollx_l[6] = c15_q[2];
assign scrollx_l[7] = c15_q[3];
assign scrollx_l[8] = h3_q[0];

assign scrolly_l[0] = h3_q[1];
assign scrolly_l[1] = h3_q[2];
assign scrolly_l[2] = h3_q[3];

assign e52a_y = ~n186_x0; // e52a
assign h162_y = ~n186_x3; // h162
always @(posedge e52a_y) begin
    h156_q <= h162_y; // h156
end
always @(posedge n186_x0) begin
    n186_x3_dly <= h156_q; // g151
end

assign n186_x3_dly_n = ~n186_x3_dly; // g151
assign e14a_y = e52a_y; // e14a
always @(posedge e14a_y) begin
    c25_q <= c25_d; // c25
end
always @(posedge e14a_y) begin
    {e22_q,f8_q} <= {scrollx[7],scrollx[8]}; // e22, f8
end
assign j18a_y = scrolly[0] | pin_test; // j18a
always @(posedge e14a_y) begin
    {h14_q,h17_q,h20_q} <= {j18a_y,scrolly[1],scrolly[2]}; // h14, h17, h20
end
always @(posedge n186_x0) begin
    c7_q <= c25_q[0]; // c7
end
always @(posedge n186_x0) begin
    {c15_q,h3_q} <= {c15_d,h3_d}; // c15, h3
end
assign j6a_y = ~pin_test; // j6a
assign scrolly_t2b_x[0] = pin_test ? ~h3_q[1] : ~scrolly[0]; // j8b
assign scrolly_t2b_x[1] = pin_test ? ~h3_q[2] : ~scrolly[1]; // j10b
assign scrolly_t2b_x[2] = pin_test ? ~h3_q[3] : ~scrolly[2]; // j9a
assign scrolly_mux[0] = ~scrolly_t2b_x[0]; // j8a
assign scrolly_mux[1] = ~scrolly_t2b_x[1]; // j7b
assign scrolly_mux[2] = ~scrolly_t2b_x[2]; // j6b
assign scrollx_xor[3] = c7_q ^ h36_y; // c5a
assign scrollx_xor[4] = c15_q[0] ^ h36_y; // c11a
assign scrollx_xor[5] = c15_q[1] ^ h36_y; // c13a
assign scrollx_xor[6] = c15_q[2] ^ h36_y; // c10
assign scrollx_xor[7] = c15_q[3] ^ h36_y; // b10
assign scrollx_xor[8] = h3_q[0] ^ h36_y; // b8a
assign scrolly_xor[0] = scrolly_mux[0] ^ h36_y; // j15a
assign scrolly_xor[1] = scrolly_mux[1] ^ h36_y; // j14
assign scrolly_xor[2] = scrolly_mux[2] ^ h36_y; // j11a
endmodule
